// tick.c - Minimal C implementation with callback trampoline
#include "tick.h"
#include <stdlib.h>
#include <string.h>

// Forward declaration for the Go callback bridge
extern void goTickCallback(void* goFunc, const TickResult* r, void* ctx);

static void trampoline(const TickResult* r, void* ctx) {
    void* goFunc = *(void**)ctx;
    goTickCallback(goFunc, r, ctx);
}

int process_ticks_async(const Tick* ticks, size_t n, void (*cb)(const TickResult*, void*), void* ctx) {
    // Store the Go function pointer at the start of ctx for the trampoline
    for (size_t i = 0; i < n; i++) {
        TickResult result = {
            .ts = ticks[i].ts,
            .price = ticks[i].price,
            .status = (ticks[i].price > 0) ? 1 : 0
        };
        cb(&result, ctx);
    }
    return 0;
}
```

